          "title": "〔注7〕文卡特什·拉奥（Venkatesh Rao）与“认知重商主义”（Cognitive Mercantilism）",
          "content": "文卡特什·拉奥是硅谷知名长文博客 Ribbonfarm 的创始人。他在《认知重商主义》中将当下对 AI 替代脑力劳动的恐慌，类比于工业革命前夕欧洲的重商主义思维：重商主义者误以为社会总需求是固定死水，效率提升只会导致产能过剩与劳工失业；而历史证明，当农业人口从维持温饱的“生存型体力劳动”中解放出来后，人类的消费欲望与新产业门类随之爆发。同理，当人类将维持科层运转的日常文书、基础代码等“生存型认知（Subsistence Cognition）”移交给 AI 后，心智算力将转向此前因成本过高而从未被开发过的新型认知需求。"
