            "BT：你说的“投入不足”具体指谁？\nSS：模型实验室，以及整个市场激励结构。实验室困在自己的正反馈循环里：做基础研究、训出更强的模型，估值就能翻倍甚至翻四倍。这套逻辑默认技术迟早会自动扩散、产生经济价值。"
