            "现代文明大半建立在化学反应之上，无论是用高炉把氧化铁还原成金属铁，还是燃烧燃料发电。化学反应的本质，是重新排列原子最外层电子的结合方式。比如把一个钠原子和一个氯原子放在一起，钠最外层的电子会转移到氯的外层电子壳层里，通过离子键结合成氯化钠，也就是食盐。"
