            "目前同位素的应用受制于制造难度与高昂成本。按克计算，同位素是地球上最贵的材料之一，供应链也极其脆弱。医学显像广泛使用的锝-99m 靠母体同位素钼-99 衰变产生，而全球钼-99 只靠寥寥几座老旧核反应堆生产；2024 年其中几座停堆检修，直接引发了全球断供〔注2〕。如果能更便宜、更方便地制造同位素，就能带来更廉价的癌症疗法、更好的核能材料乃至全新的功能材料。"
