          "content": "锝-99m（Tc-99m）占全球核医学诊断显像用量的 80% 以上（每年约 4,000 万次检查，用于心肌灌注、骨转移癌筛查等），但它的半衰期仅 6 小时，无法长期储存，必须由医院采购半衰期 66 小时的母体核素“钼-99”（Mo-99）发生器（俗称“锝奶牛”）现场淋洗提取。然而全球逾 90% 的钼-99 长期依赖建于 1950～1960 年代的寥寥五六座老旧高通量研究用裂变堆（分布于荷兰、比利时、南非、澳大利亚等）。一旦其中一两座反应堆因腐蚀检修停堆，全球医院核医学科就会立刻陷入显像剂断供。"
