          "content": "回旋加速器通过交变电场加速质子（带正电）去轰击靶原子核（同样带正电）。由于同性电荷间的库仑排斥力（Coulomb Barrier），绝大多数入射质子只会与靶原子的外层电子发生碰撞并转化为热量散失，平均约 800 个高速质子中仅有 1 个能隧穿进入原子核触发核反应。这导致其电光/核转化效率不足 0.15%，折算下来每合成 1 克氟-18 同位素需耗电 0.7 TWh（7 亿度电），决定了加速器路线无法用于吨级工业核素生产。"
