      "footnotes": {
        "1": {
          "title": "〔注1〕内华达州“斜坡村”（Incline Village）：硅谷富豪的头号避税飞地",
          "content": "Incline Village 位于太浩湖（Lake Tahoe）东北岸，在行政区划上属于内华达州瓦肖县，距离加州硅谷仅数小时车程（或 40 分钟私人飞机航程）。由于加州拥有全美最高的个人所得税率（最高边际税率达 13.3%～14.4%，且将资本利得视为普通收入全额征税），而相邻的内华达州个人所得税与资本利得税均为 0%，因此斜坡村长期以来是硅谷亿万富翁与风投家规避加州高额州税的首选迁居地。"
        },
        "2": {
          "title": "〔注2〕帕克·康拉德（Parker Conrad）揭露的“未实现资本利得 + 超级投票权”税务死局",
          "content": "在现行美税制（实现制 Realization Principle）下，创始人持有的公司股权只有在实际抛售套现（或上市解禁减持）时才产生纳税义务。而加州富豪税提案（及类似财富税提案）有两大致命会计机制缺陷：① 对未上市独角兽的纸面估值（Unrealized Gains）强行征税，而私营企业股权缺乏二级市场流动性，创始人手里根本没有数千万美元现金交税；② 更致命的是，法案在计算创始人持股市值时，按创始人持有的“超级投票权比例”（如创始人占股 10% 但通过 AB 股结构拥有 50% 投票权）而非“经济受益权比例”来核定应税基数，导致创始人面临的实际税率远超 5%，一旦独角兽后续估值回调甚至破产，已缴纳的税款也无法退还。"
        },
        "3": {
          "title": "〔注3〕为什么加州州长纽森与教师工会反而反对“富豪税”？",
          "content": "加州财政收入结构高度依赖金字塔尖 1% 富豪缴纳的个人所得税与资本利得税（占全州所得税总额近半）。加州州长纽森（Gavin Newsom）深知，一旦单州强推针对存量净资产的财富税，极易触发硅谷顶级创始人与风投基金集体将税务居民身份迁往内华达州或得克萨斯州，从而永久性掏空加州每年常规的百亿级所得税税基；而加州教师协会（CTA）等工会反对，则是因为该公投提案会绕开或挤占加州宪法第 98 号提案（Prop 98）规定的公共教育预算保底分配机制。"
        },
        "4": {
          "title": "〔注4〕面向 AI 智能体的“隐形广告”（Invisible Ads / Prompt-injected Sponsorships）",
          "content": "当越来越多用户不再亲自点开媒体网页，而是让 ChatGPT、Claude 或 Perplexity 等 AI 智能体抓取网页并生成摘要时，媒体赖以生存的传统视觉横幅广告（Banner Ads）曝光量归零。为此，部分数字出版商开始测试在网页 HTML 源码或隐藏文本层中植入专门面向大模型的结构化赞助商推荐语（人类肉眼不可见，但爬虫与 LLM 必读），试图逼迫 AI 在向用户输出总结回答时顺带口播赞助商信息。"
        },
        "5": {
          "title": "〔注5〕曼哈顿第五大道 666 号（666 Fifth Avenue）债务解困案",
          "content": "库什纳家族于 2007 年地产周期顶点以 18 亿美元高杠杆买下曼哈顿第五大道 666 号办公楼，随后因金融危机陷入长期资不抵债，且有高达 12 亿美元的抵押贷款于 2018～2019 年到期。最终，由卡塔尔主权财富基金（QIA）作为核心出资方（LP）的博枫资产管理公司（Brookfield）出面签下长达 99 年的整栋租赁协议并一次性预付全部租金，帮助库什纳家族结清了银行违约债务危机。"
        }
      },
